Definition DIM3 (m : word -> option byte) (s w h d : Z) : word -> option byte :=
  wbytes (wbytes (wbytes (wbytes (wbytes (wbytes m
    (Z_to_bv 64 (s - 76)) (w4 (Z_to_bv 64 0)))
    (Z_to_bv 64 (s - 80)) (w4 (Z_to_bv 64 0)))
    (Z_to_bv 64 (s - 84)) (w4 (Z_to_bv 64 0)))
    (Z_to_bv 64 (s - 76)) (w4 (Z_to_bv 64 w)))
    (Z_to_bv 64 (s - 80)) (w4 (Z_to_bv 64 h)))
    (Z_to_bv 64 (s - 84)) (w4 (Z_to_bv 64 d)).

