(* [comment removed for export] *)
Definition GVA (m : word -> option byte) (s cellp : Z) (ret : word) (regs : bvmap 5 word) : word -> option byte :=
  wbytes (FRM9 m s ret regs) (Z_to_bv 64 cellp) (w4 (Z_to_bv 64 (-1))).

Section Segs.
Variable rom : word -> option byte.

  (* [comment removed for export] *)
  Lemma gv_A : forall regs m (s pixs typ cellp : Z) (v : pixv) (ret : word),
    (96 <= s)%Z -> (s <= cellp)%Z -> (cellp + 4 < 2 ^ 64)%Z -> (1 <= pixs)%Z -> PIXat m pixs v -> (pixs + 64 <= s - 96)%Z -> p_cmap v = 0%Z ->
    (typ = 4 \/ typ = 5)%Z ->
    store_ok SEGS m (Z_to_bv 64 (s - 96)) 96 = true -> store_ok SEGS m (Z_to_bv 64 cellp) 4 = true ->
    getr regs 2 = Z_to_bv 64 s -> getr regs 1 = ret -> getr regs 10 = Z_to_bv 64 pixs -> getr regs 11 = Z_to_bv 64 1 -> getr regs 12 = Z_to_bv 64 typ ->
    getr regs 13 = Z_to_bv 64 0 -> getr regs 14 = Z_to_bv 64 0 -> getr regs 15 = Z_to_bv 64 0 -> getr regs 16 = Z_to_bv 64 cellp ->
    exists regs',
      msteps SEGS (mkst regs (0x1d8f0 : word) m rom) (mkst regs' (0x1da5c : word) (GVA m s cellp ret regs) rom)
      /\ getr regs' 2 = Z_to_bv 64 (s - 96) /\ getr regs' 9 = Z_to_bv 64 pixs /\ getr regs' 21 = Z_to_bv 64 1 /\ getr regs' 23 = Z_to_bv 64 typ
      /\ getr regs' 18 = Z_to_bv 64 0 /\ getr regs' 19 = Z_to_bv 64 0 /\ getr regs' 20 = Z_to_bv 64 0 /\ getr regs' 22 = Z_to_bv 64 cellp
