  (* [comment removed for export] *)
  Lemma gv_B : forall regs m (s pixs cellp : Z) (v : pixv),
    (96 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= pixs)%Z -> PIXat m pixs v -> (pixs + 64 <= s - 96)%Z -> p_d v = 8%Z -> (1 <= cellp < 2 ^ 64)%Z ->
    store_ok SEGS m (Z_to_bv 64 (s - 96)) 96 = true ->
    getr regs 2 = Z_to_bv 64 (s - 96) -> getr regs 9 = Z_to_bv 64 pixs -> getr regs 21 = Z_to_bv 64 1 ->
    getr regs 18 = Z_to_bv 64 0 -> getr regs 19 = Z_to_bv 64 0 -> getr regs 20 = Z_to_bv 64 0 -> getr regs 22 = Z_to_bv 64 cellp ->
    exists regs',
      msteps SEGS (mkst regs (0x1da5c : word) m rom) (mkst regs' (0x1dbf4 : word) (DIM3 m s (p_w v) (p_h v) 8) rom)
      /\ getr regs' 2 = Z_to_bv 64 (s - 96)
      /\ regs_agree (fun x => In x [1; 2; 10; 11; 12; 13; 14]%list) regs regs'.
