    rdn SEGS m (Z_to_bv 64 (s - 80)) 4 = Some (w4 (Z_to_bv 64 (p_h v))) ->
    rdn SEGS m (Z_to_bv 64 (s - 76)) 4 = Some (w4 (Z_to_bv 64 (p_w v))) ->
    getr regs 2 = Z_to_bv 64 (s - 96) -> getr regs 9 = Z_to_bv 64 pixs -> getr regs 21 = Z_to_bv 64 1 -> getr regs 23 = Z_to_bv 64 typ ->
    exists regs',
      msteps SEGS (mkst regs (0x1dbf4 : word) m rom) (mkst regs' (0x1dc68 : word) m rom)
      /\ getr regs' 2 = Z_to_bv 64 (s - 96) /\ getr regs' 10 = Z_to_bv 64 (4 * p_wpl v) /\ getr regs' 11 = Z_to_bv 64 typ
      /\ getr regs' 12 = Z_to_bv 64 (p_h v) /\ getr regs' 13 = Z_to_bv 64 (gev_init typ) /\ getr regs' 14 = Z_to_bv 64 0
      /\ getr regs' 15 = Z_to_bv 64 (p_w v) /\ getr regs' 16 = Z_to_bv 64 1 /\ getr regs' 8 = Z_to_bv 64 (p_data v)
      /\ regs_agree (fun x => In x [1; 8; 10; 11; 12; 13; 14; 15; 16]%list) regs regs'.
Proof.
