  (* [comment removed for export] *)
  Lemma gv_I1 : forall regs m (typ e p : Z) (b : byte),
    (typ = 4 \/ typ = 5)%Z -> (-1 <= e <= 100000)%Z -> (0 <= p)%Z -> (p + 4 < 2 ^ 64)%Z ->
    m (Z_to_bv 64 (xor3 p)) = Some b ->
    getr regs 11 = Z_to_bv 64 typ -> getr regs 13 = Z_to_bv 64 e -> getr regs 6 = Z_to_bv 64 p ->
    exists regs',
      msteps SEGS (mkst regs (0x1dc88 : word) m rom) (mkst regs' (0x1dc78 : word) m rom)
      /\ getr regs' 5 = Z_to_bv 64 (gev_step typ e (u b))
      /\ regs_agree (fun x => In x [5; 7; 28; 29]%list) regs regs'.
Proof.
