  (* [comment removed for export] *)
  Lemma gv_I2 : forall (last : bool) regs m (j w p nv : Z),
    (0 <= j < w)%Z -> (w < 2 ^ 31)%Z -> (0 <= p)%Z -> (p + 4 < 2 ^ 64)%Z -> (if last then j + 1 = w else j + 1 < w)%Z ->
    getr regs 17 = Z_to_bv 64 j -> getr regs 15 = Z_to_bv 64 w -> getr regs 21 = Z_to_bv 64 1 -> getr regs 16 = Z_to_bv 64 1 ->
    getr regs 6 = Z_to_bv 64 p -> getr regs 5 = Z_to_bv 64 nv ->
    exists regs',
      msteps SEGS (mkst regs (0x1dc78 : word) m rom) (mkst regs' (if last then (0x1dc58 : word) else (0x1dc88 : word)) m rom)
      /\ getr regs' 17 = Z_to_bv 64 (j + 1) /\ getr regs' 6 = Z_to_bv 64 (p + 1) /\ getr regs' 13 = Z_to_bv 64 nv /\ getr regs' 5 = Z_to_bv 64 nv
      /\ regs_agree (fun x => In x [6; 13; 17]%list) regs regs'.
