  (* [comment removed for export] *)
  Lemma gv_OH : forall regs m (w line : Z),
    (1 <= w < 2 ^ 31)%Z -> getr regs 15 = Z_to_bv 64 w -> getr regs 8 = Z_to_bv 64 line ->
    exists regs',
      msteps SEGS (mkst regs (0x1dc68 : word) m rom) (mkst regs' (0x1dc88 : word) m rom)
      /\ getr regs' 17 = Z_to_bv 64 0 /\ getr regs' 6 = Z_to_bv 64 line
      /\ regs_agree (fun x => In x [6; 17]%list) regs regs'.
