  (* [comment removed for export] *)
  Lemma gv_ON : forall (last : bool) regs m (i h line stride nv : Z),
    (0 <= i < h)%Z -> (h < 2 ^ 31)%Z -> (0 <= line)%Z -> (0 <= stride)%Z -> (line + stride < 2 ^ 64)%Z -> (if last then i + 1 = h else i + 1 < h)%Z ->
    getr regs 14 = Z_to_bv 64 i -> getr regs 12 = Z_to_bv 64 h -> getr regs 21 = Z_to_bv 64 1 -> getr regs 8 = Z_to_bv 64 line ->
    getr regs 10 = Z_to_bv 64 stride -> getr regs 5 = Z_to_bv 64 nv ->
    exists regs',
      msteps SEGS (mkst regs (0x1dc58 : word) m rom) (mkst regs' (if last then (0x1dde0 : word) else (0x1dc68 : word)) m rom)
      /\ getr regs' 14 = Z_to_bv 64 (i + 1) /\ getr regs' 8 = Z_to_bv 64 (line + stride) /\ getr regs' 13 = Z_to_bv 64 nv /\ getr regs' 5 = Z_to_bv 64 nv
      /\ regs_agree (fun x => In x [8; 13; 14]%list) regs regs'.
Proof.
