  (* [comment removed for export] *)
  Lemma gv_E : forall regs r0 m (s cellp nv : Z) (ret : word),
    (96 <= s)%Z -> (s <= cellp)%Z -> (cellp + 4 < 2 ^ 64)%Z -> (0 <= nv <= 255)%Z -> ret_ok ret -> cellsZ m (frameM s ret r0) ->
    store_ok SEGS m (Z_to_bv 64 cellp) 4 = true ->
    getr regs 2 = Z_to_bv 64 (s - 96) -> getr regs 22 = Z_to_bv 64 cellp -> getr regs 5 = Z_to_bv 64 nv ->
    exists regs',
      msteps SEGS (mkst regs (0x1dde0 : word) m rom) (mkst regs' ret (wbytes m (Z_to_bv 64 cellp) (w4 (Z_to_bv 64 nv))) rom)
      /\ getr regs' 2 = Z_to_bv 64 s /\ getr regs' 1 = ret /\ getr regs' 10 = Z_to_bv 64 0
      /\ (forall x, In x [8; 9; 18; 19; 20; 21; 22; 23]%bv -> getr regs' x = getr r0 x)
      /\ regs_agree (fun x => In x [1; 2; 8; 9; 10; 18; 19; 20; 21; 22; 23]%list) regs regs'.
Proof.
